"""Ordinary socket clients for the approved disposable release; no staff inputs."""
import json
from pathlib import Path
import re
import secrets
import socket
import time

ROOT=Path(__file__).resolve().parent
plan=json.loads((ROOT/'plan.json').read_text())
clients={}
credentials={key:{'name':'ItemRepair'+key+plan['tag'][-6:], 'password':secrets.token_urlsafe(24)} for key in ('Dusk','Dawn')}
(ROOT/'player-private.json').write_text(json.dumps(credentials))
history=[]

def receive(conn, seconds):
    """Read actual player output, stripping ANSI and telnet negotiation bytes."""
    end=time.monotonic()+seconds
    chunks=[]
    conn.settimeout(.1)
    while time.monotonic()<end:
        try:
            data=conn.recv(65536)
            if not data: break
            chunks.append(data)
        except socket.timeout: pass
    data=b''.join(chunks)
    data=re.sub(b'\xff[\xfb-\xfe].',b'',data)
    data=re.sub(b'\xff\xfa.*?\xff\xf0',b'',data,flags=re.S)
    output=re.sub(r'\x1b\[[0-9;]*[a-zA-Z]','',data.decode('utf-8','replace')).replace('\r','')
    for entry in credentials.values(): output=output.replace(entry['password'],'[private]')
    return output

print('ORDINARY_SOCKET_DRIVER_READY',flush=True)
try:
    while not (ROOT/'socket-stop').exists():
        jobpath=ROOT/'socket-job.json'
        if not jobpath.exists():
            time.sleep(.1); continue
        job=json.loads(jobpath.read_text(encoding='utf-8-sig'))
        results=[]
        try:
            for entry in job['steps']:
                who=entry['player']; action=entry.get('action','send'); credential=credentials[who]
                if action in ('open','reconnect'):
                    if who in clients: clients.pop(who).close()
                    clients[who]=socket.create_connection(('127.0.0.1',plan['ports']['telnet']),timeout=5)
                    output=receive(clients[who],.5)
                    command='[open ordinary socket]'
                elif action in ('create','login'):
                    command='[ordinary '+action+'; authentication omitted]'
                    verb='create' if action=='create' else 'connect'
                    clients[who].sendall((verb+' '+credential['name']+' '+credential['password']+'\r\n').encode())
                    output=receive(clients[who],entry.get('wait',1.0))
                else:
                    command=entry.get('command','')
                    if command: clients[who].sendall((command+'\r\n').encode())
                    output=receive(clients[who],entry.get('wait',.7))
                result={'player':credential['name'],'command':command,'output':output,'expected':entry.get('expected'),'time':time.time()}
                history.append(result);results.append(result)
            response={'id':job['id'],'results':results}
        except Exception as error:
            response={'id':job['id'],'results':results,'error':repr(error)}
        (ROOT/'socket-history.json').write_text(json.dumps(history,indent=2),encoding='utf-8')
        (ROOT/'socket-result.json').write_text(json.dumps(response,indent=2),encoding='utf-8')
        jobpath.unlink()
finally:
    for conn in clients.values(): conn.close()
